sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   //Type appropriate comment here, and begin script below
   //    alert(newValue);
   var ga = new GlideAjax('AssetManagementUtils');
   ga.addParam('sysparm_name', 'vipChecker');
   ga.addParam('sysparm_requestor', newValue);
   ga.getXMLAnswer(setPriority);
}	

function setPriority(isVip) {
	// alert(parseInt(isVip));
	var targetField = g_form.getDisplayBox('requestor');
	if(parseInt(isVip)) {
		// alert("VIP User");
		g_form.setValue('priority', 1);
		targetField.style.backgroundColor = "Red";
	}
	else {
		// alert("Not VIP User");
		targetField.style.backgroundColor = '';
	}

}
